import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        try (PrintWriter w = new PrintWriter(new FileWriter("harga.txt"))) {
            while (in.hasNextLine()) {
                w.println(in.nextLine());
            }
        }
        int total = 0, banyak = 0;
        try (Scanner s = new Scanner(new File("harga.txt"))) {
            while (s.hasNextInt()) {
                total += s.nextInt();
                banyak++;
            }
        }
        System.out.println("Total: " + total);
        System.out.println("Banyak: " + banyak);
    }
}
